/* ---------- films: common elements in winemaking (ch.7) ---------- */
const STEEL=(x,y,w,h,o)=>fTank(x,y,w,h,o);
FILMS.push(
{id:"wm1",sec:"c",ch:"vin",ic:"quiz",t:I3("In cantina: l'uva, l'ossigeno e la solforosa","Au chai : le raisin, l'oxygène et le soufre","In the winery: grapes, oxygen and sulfur dioxide"),s:[
 {h:I3("Due approcci alla vinificazione","Deux approches de la vinification","Two approaches to winemaking"),
  c:I3("La vinificazione parte dall'uva e arriva al vino: l'uva viene lavorata, i lieviti trasformano gli zuccheri in alcol, poi il vino si conserva fino al confezionamento e alla vendita. Niente di tutto questo avviene senza centinaia di scelte umane. Alcuni produttori controllano ogni fase per ottenere uno stile preciso; altri intervengono il meno possibile, e i loro vini, a volte chiamati naturali, hanno spesso un gusto molto diverso. La maggior parte si colloca a metà strada.",
   "La vinification part du raisin et aboutit au vin : le raisin est préparé, les levures transforment les sucres en alcool, puis le vin est conservé jusqu'au conditionnement et à la vente. Rien de tout cela ne se fait sans des centaines de choix humains. Certains vinificateurs contrôlent chaque étape pour obtenir un style précis ; d'autres interviennent le moins possible, et leurs vins, parfois appelés nature, ont souvent un goût très différent. La plupart se situent entre les deux.",
   "Winemaking starts with grapes and ends with wine: the grapes are processed, yeast converts the sugars into alcohol, and the wine is stored until packaging and sale. None of this happens without hundreds of human choices. Some winemakers control every step to achieve a precise style; others intervene as little as possible, and their wines, sometimes called natural wines, often taste very different. Most sit somewhere in between."),
  v:()=>fSvg(fFlow([{t:I3("uva","raisin","grapes"),io:1},{t:I3("lavorazione","préparation","processing")},{t:I3("fermentazione","fermentation","fermentation")},{t:I3("conservazione","élevage","storage")},{t:I3("confezionamento","conditionnement","packaging"),io:1}],-1,{per:3,bh:30,y0:14,gy:16,stag:1})+fD(1.5,`<rect x="30" y="130" width="260" height="10" rx="5" fill="url(#appr)"/><defs><linearGradient id="appr"><stop offset="0" stop-color="#4fa8a2"/><stop offset="1" stop-color="#d4a23a"/></linearGradient></defs>`+fT(40,160,w3("controllo","contrôle","control"),9.5,"#9fd3f0","start")+fT(280,160,w3("intervento minimo","intervention minimale","minimal intervention"),9.5,"#f3cd8a","end")))},
 {h:I3("Le parti dell'acino","Les constituants du raisin","The parts of the grape"),
  c:I3("La pruina, lo strato ceroso sulla buccia, contiene lieviti che possono fermentare il vino. La buccia e lo strato subito sotto concentrano gli aromi tipici della varietà, il colore e i tannini, molto più abbondanti nelle uve nere. La polpa è soprattutto acqua, poi zucchero, indispensabile ai lieviti per fare alcol, e acidi: soprattutto tartarico e poi malico, che restano nel vino. Semi e raspi contengono tannini; i semi anche oli amari. I raspi sono disponibili solo con la vendemmia a mano.",
   "La pruine, la couche cireuse sur la peau, contient des levures capables de fermenter le vin. La peau et la zone juste dessous concentrent les arômes typiques du cépage, la couleur et les tanins, bien plus abondants dans les raisins noirs. La pulpe est surtout de l'eau, puis du sucre, indispensable aux levures pour produire l'alcool, et des acides : surtout tartrique puis malique, qui restent dans le vin. Pépins et rafles contiennent des tanins ; les pépins aussi des huiles amères. Les rafles ne sont disponibles qu'en vendange manuelle.",
   "The bloom, the waxy coating on the skin, carries yeasts that can ferment the wine. The skin and the layer just beneath hold the variety's signature flavours, the colour and the tannins, much higher in black grapes. The pulp is mostly water, then sugar, which the yeast needs to make alcohol, and acids: mainly tartaric, then malic, which remain in the wine. Seeds and stems contain tannins; seeds also bitter oils. Stems are only available if grapes are hand-picked."),
  v:()=>fSvg(`<path d="M120 20V50" stroke="#6b8a3a" stroke-width="5"/><circle cx="120" cy="110" r="62" fill="#4e1b44"/><circle cx="120" cy="110" r="56" fill="#c9d48a"/><circle cx="120" cy="110" r="64" fill="none" stroke="rgba(230,230,240,.6)" stroke-width="3"/>${[[106,102],[134,118]].map(([x,y])=>`<ellipse cx="${x}" cy="${y}" rx="6" ry="10" fill="#8a5a33"/>`).join("")}`+fCall(170,70,215,30,w3("pruina: lieviti","pruine : levures","bloom: yeasts"),.3)+fCall(176,110,215,72,w3("buccia: aromi, colore, tannini","peau : arômes, couleur, tanins","skin: flavour, colour, tannin"),1)+fCall(150,140,215,114,w3("polpa: acqua, zucchero, acidi","pulpe : eau, sucre, acides","pulp: water, sugar, acids"),1.7)+fCall(120,126,215,160,w3("semi: tannini, oli amari","pépins : tanins, huiles amères","seeds: tannin, bitter oils"),2.4)+fCall(120,30,40,30,w3("raspo: tannini","rafle : tanins","stem: tannin"),3.1))},
 {h:I3("I tannini","Les tanins","Tannins"),
  c:I3("Molti composti chimici sono classificati come tannini. All'invaiatura hanno un gusto molto amaro e astringente; con la maturazione dell'uva amarezza e astringenza diminuiscono. Anche il rovere può apportare tannini, sia ai rossi sia ai bianchi.",
   "De nombreux composés chimiques sont classés comme tanins. À la véraison ils ont un goût très amer et astringent ; avec la maturation du raisin, amertume et astringence diminuent. Le chêne peut aussi apporter des tanins, aux rouges comme aux blancs.",
   "Many chemical compounds are classed as tannins. At véraison they taste very bitter and astringent; as the grapes ripen, the bitterness and astringency fall. Oak can also contribute some tannins, to both red and white wines."),
  v:()=>fSvg(`<path d="M40 40C110 50 160 130 280 150" stroke="#8c1d40" stroke-width="5" fill="none" stroke-dasharray="300" stroke-dashoffset="300"><animate attributeName="stroke-dashoffset" from="300" to="0" dur="2.6s" fill="freeze"/></path><path d="M30 170H290" stroke="#7d6a70"/>`+fT(60,30,w3("amaro, astringente","amer, astringent","bitter, astringent"),10,"#f3cd8a","start")+fT(280,140,w3("maturo","mûr","ripe"),10,"#f3cd8a","end")+fT(160,190,w3("invaiatura → vendemmia","véraison → vendanges","véraison → harvest"),9)+fD(2.4,fBarrel(240,70,.8)+fChip(240,40,w3("anche dal rovere","aussi du chêne","also from oak"))))},
 {h:I3("L'ossigeno durante la vinificazione","L'oxygène pendant la vinification","Oxygen during winemaking"),
  c:I3("L'ossigeno reagisce con il mosto e con il vino: è l'ossidazione, a volte positiva, a volte negativa. Chi vuole un vino dominato dal frutto primario lo combatte: usa antiossidanti come l'anidride solforosa, vendemmia di notte quando fa fresco e le reazioni sono più lente, mantiene l'uva fredda fino in cantina e riempie le attrezzature di anidride carbonica o azoto. È la vinificazione protettiva, o anaerobica. Altri pensano che un po' più di ossigeno dia complessità: è una scelta di stile.",
   "L'oxygène réagit avec le moût et le vin : c'est l'oxydation, parfois positive, parfois négative. Qui veut un vin dominé par le fruit primaire le combat : il utilise des antioxydants comme le dioxyde de soufre, vendange la nuit quand il fait frais et que les réactions sont plus lentes, garde le raisin froid jusqu'au chai et remplit le matériel de gaz carbonique ou d'azote. C'est la vinification protectrice, ou anaérobie. D'autres estiment qu'un peu plus d'oxygène apporte de la complexité : c'est une question de style.",
   "Oxygen reacts with grape juice and wine: this is oxidation, sometimes positive, sometimes negative. Winemakers wanting a wine dominated by primary fruit fight it: they use antioxidants such as sulfur dioxide, pick at night when it is cool and reactions are slower, keep the grapes chilled until they reach the winery, and fill equipment with carbon dioxide or nitrogen. This is protective, or anaerobic, winemaking. Others argue that more oxygen contact builds complexity: it is a question of style."),
  v:()=>fSvg(STEEL(110,40,100,124,{col:WHITE,lv:.6})+fD(.8,`<rect x="115" y="56" width="90" height="40" fill="rgba(159,211,240,.35)"/>`+fChip(160,74,"CO₂ / N₂","#2b7a75"))+[0,1,2].map(i=>`<text x="${40+i*14}" y="80" font-size="9" fill="#b5334a" font-weight="800">O₂<animateTransform attributeName="transform" type="translate" values="0 0;40 0;34 0" dur="2s" begin="${i*.3}s" repeatCount="indefinite"/></text>`).join("")+`<path d="M100 60V110" stroke="#b5334a" stroke-width="3"/>`+fChip(260,60,"SO₂")+fChip(260,100,w3("uva fredda","raisin froid","chilled grapes")))},
 {h:I3("L'ossigeno durante l'affinamento","L'oxygène pendant l'élevage","Oxygen during maturation"),
  c:I3("I vini fatti in modo protettivo raramente traggono vantaggio dall'ossigeno durante l'affinamento: si conservano in vasche inerti e stagne, tenute piene, di acciaio inox o di cemento rivestito di resina epossidica. I vini affinati in modo ossidativo stanno invece in recipienti di legno, di solito rovere: il legno non perde vino ma lascia passare piccole quantità di ossigeno. Questo ammorbidisce i tannini dei rossi e aggiunge complessità: il frutto primario sfuma e compaiono aromi terziari come cuoio e terra. I rossi schiariscono e virano al bruno, i bianchi si scuriscono verso l'arancio.",
   "Les vins élaborés de façon protectrice profitent rarement de l'oxygène pendant l'élevage : on les garde dans des cuves inertes et étanches, pleines, en inox ou en béton revêtu de résine époxy. Les vins élevés de façon oxydative sont en revanche dans des contenants en bois, en général du chêne : le bois est étanche au vin mais laisse passer un peu d'oxygène. Cela assouplit les tanins des rouges et ajoute de la complexité : le fruit primaire s'estompe et des arômes tertiaires comme le cuir et la terre apparaissent. Les rouges pâlissent et tirent vers le brun, les blancs foncent vers l'orangé.",
   "Wines made protectively rarely benefit from oxygen during maturation: they are kept in inert, airtight vessels that are kept completely full, made of stainless steel or epoxy-lined concrete. Wines matured oxidatively are stored in wooden vessels, usually oak: wood is watertight but not airtight, letting small amounts of oxygen through. This softens red-wine tannins and adds complexity: primary fruit fades and tertiary characters such as leather and earth develop. Reds become paler with a hint of brown; whites deepen with a hint of orange."),
  v:()=>fSvg(STEEL(30,50,80,110,{col:RED,lv:.95,lab:w3("inerte, pieno","inerte, plein","inert, full")})+fBarrel(230,110,1.6,{cut:1,col:RED,ox:1})+fD(1.6,fGlass(160,70,"#7a1530",.9)+fArrow("M176 60H196")+fGlass(212,46,"#8a3a2a",.9)))},
 {h:I3("Dimensioni del recipiente e vini ossidativi","Taille du contenant et vins oxydatifs","Vessel size and oxidative wines"),
  c:I3("Quanto il vino si ossida dipende dalla grandezza del recipiente e dal tempo. Le barrique da 225 litri hanno più effetto dei recipienti grandi perché offrono più superficie di legno in proporzione al vino: raramente si superano i due anni. Nei recipienti grandi si può affinare più a lungo. L'effetto aumenta se il recipiente non è pieno, tecnica usata per vini volutamente ossidativi come Oloroso, Tawny Port e Rutherglen Muscat, con note di caramello, mou e frutta secca. Per la maggior parte dei vini però troppo ossigeno è un difetto: il vino è ossidato e, nei casi estremi, i batteri lo trasformano in aceto.",
   "L'oxydation dépend de la taille du contenant et de la durée. Les barriques de 225 litres ont plus d'effet que les grands contenants car elles offrent plus de surface de bois par rapport au vin : on y dépasse rarement deux ans. Dans les grands contenants l'élevage peut durer plus longtemps. L'effet augmente si le contenant n'est pas plein, technique utilisée pour des vins volontairement oxydatifs comme l'Oloroso, le Tawny Port et le Rutherglen Muscat, aux notes de caramel, toffee et fruits secs. Pour la plupart des vins, trop d'oxygène est un défaut : le vin est oxydé et, à l'extrême, les bactéries le transforment en vinaigre.",
   "How much a wine oxidises depends on vessel size and time. 225-litre barriques have more effect than large vessels because they offer more wood surface relative to the wine: wines rarely stay in them more than two years. Larger vessels allow longer maturation. The effect grows if the vessel is not completely full, a technique used for deliberately oxidative wines such as Oloroso, Tawny Port and Rutherglen Muscat, with caramel, toffee and nutty notes. For most wines, though, too much oxygen is a fault: the wine is oxidised and, in extreme cases, bacteria turn it into vinegar."),
  v:()=>fSvg(fBarrel(70,90,1)+fT(70,140,"225 l",10)+`<ellipse cx="190" cy="90" rx="56" ry="46" fill="url(#fwood)" stroke="#4e321c"/>`+fT(190,150,"> 2000 l",10)+fD(1.4,fBarrel(270,90,1,{cut:1,col:"#a8642a",ox:1})+fChip(270,140,w3("scolmo","vidange","part-filled"),"#a8642a")))},
 {h:I3("L'anidride solforosa","Le dioxyde de soufre","Sulfur dioxide"),
  c:I3("L'anidride solforosa, SO₂, è quasi indispensabile: è antiossidante e antisettica, protegge l'uva appena raccolta e si dosa lungo tutta la vinificazione. I livelli massimi sono fissati per legge, perché è tossica in dosi alte e può dare allergie anche a dosi basse; un po' si forma naturalmente in fermentazione. Come antiossidante, reagendo diventa «combinata» e non protegge più: va controllata e reintegrata. Come antisettico uccide i lieviti e i batteri indesiderati, mentre il lievito principale della fermentazione la tollera. Troppa rende il vino duro e povero di frutto; pochi produttori non la usano affatto.",
   "Le dioxyde de soufre, SO₂, est presque indispensable : antioxydant et antiseptique, il protège le raisin juste cueilli et se dose tout au long de la vinification. Les teneurs maximales sont fixées par la loi, car il est toxique à forte dose et peut provoquer des allergies même à faible dose ; un peu se forme naturellement pendant la fermentation. Comme antioxydant, en réagissant il devient « combiné » et ne protège plus : il faut le contrôler et le compléter. Comme antiseptique, il tue levures et bactéries indésirables, alors que la levure principale de la fermentation le tolère. Trop de SO₂ rend le vin dur et pauvre en fruit ; quelques producteurs n'en utilisent pas du tout.",
   "Sulfur dioxide, SO₂, is almost indispensable: it is an antioxidant and an antiseptic, protects freshly picked grapes and is adjusted throughout winemaking. Maximum levels are set by law because it is toxic at high doses and can cause allergic reactions even at low levels; some is produced naturally during fermentation. As an antioxidant it becomes 'bound' when it reacts and no longer protects, so levels must be monitored and topped up. As an antiseptic it kills unwanted yeasts and bacteria, while the main fermentation yeast tolerates it. Too much makes a wine harsh and lacking fruit; a few producers use none at all."),
  v:()=>fSvg(fBox(30,30,120,50,w3("antiossidante: SO₂ libera → combinata","antioxydant : SO₂ libre → combiné","antioxidant: free SO₂ → bound"),{fill:"rgba(79,168,162,.45)"})+fBox(170,30,120,50,w3("antisettica: ferma lieviti e batteri indesiderati","antiseptique : bloque levures et bactéries indésirables","antiseptic: stops unwanted yeasts and bacteria"),{fill:"rgba(181,51,74,.45)"})+fD(1,[0,1,2,3].map(i=>`<circle cx="${60+i*20}" cy="130" r="7" fill="#d4a23a"><animate attributeName="fill" from="#d4a23a" to="#7d6a70" begin="${1.2+i*.4}s" dur=".6s" fill="freeze"/></circle>`).join(""))+fD(1.4,fYeast(220,130)+fBug(256,130,"#86b85a")+`<path d="M244 120l24 20M268 120l-24 20" stroke="#b5334a" stroke-width="3"/>`)+fChip(160,186,w3("limiti di legge","limites légales","legal limits")))},
 {h:I3("Di che cosa è fatto il vino","De quoi est fait le vin","What wine is made of"),
  c:I3("Ecco, a titolo indicativo, i componenti di un vino fermo secco in percentuale di volume. Acqua dal 70 al 90 per cento; etanolo dall'8 al 22, compresi i fortificati; zuccheri da tracce a circa il 20, molto variabili con lo stile; acidi dallo 0,3 all'1 per cento, soprattutto tartarico, malico e lattico; tannini e colore fino allo 0,4; centinaia di composti aromatici in quantità minime, fino allo 0,2. Queste cifre servono solo come riferimento e non sono richieste all'esame.",
   "Voici, à titre indicatif, les constituants d'un vin tranquille sec en pourcentage du volume. Eau de 70 à 90 % ; éthanol de 8 à 22 %, vins mutés compris ; sucres de traces à environ 20 %, très variables selon le style ; acides de 0,3 à 1 %, surtout tartrique, malique et lactique ; tanins et couleur jusqu'à 0,4 % ; des centaines de composés aromatiques en quantités infimes, jusqu'à 0,2 %. Ces chiffres sont donnés pour référence et ne sont pas exigés à l'examen.",
   "As a guide, these are the components of a typical still dry wine by percentage of volume. Water 70 to 90 per cent; ethanol 8 to 22, including fortified wines; sugars from traces to about 20, varying with style; acids 0.3 to 1 per cent, mainly tartaric, malic and lactic; tannins and colour up to 0.4; hundreds of aroma compounds in tiny amounts, up to 0.2. These figures are for reference only and are not required for the exam."),
  v:()=>fSvg([[I3("acqua","eau","water"),"70–90%",.85,"#7fc7ec"],[I3("etanolo","éthanol","ethanol"),"8–22%",.22,"#e9dc8c"],[I3("zuccheri","sucres","sugars"),"0,1–20%",.14,"#f3cd8a"],[I3("acidi","acides","acids"),"0,3–1%",.04,"#86b85a"],[I3("tannini e colore","tanins et couleur","tannin & colour"),"≤ 0,4%",.02,"#8c1d40"],[I3("aromi","arômes","aromas"),"≤ 0,2%",.015,"#d9774b"]].map(([l,v,f,c],i)=>`<rect x="110" y="${22+i*28}" width="${Math.max(4,f*180)}" height="18" rx="4" fill="${c}"><animate attributeName="width" from="0" to="${Math.max(4,f*180)}" dur="1.2s" begin="${i*.25}s" fill="freeze"/></rect>`+fT(102,35+i*28,tx(l),9,"#fff4dc","end")+fT(Math.max(4,f*180)+116,35+i*28,v,9,"#f3cd8a","start")).join(""))}
]},
{id:"wm2",sec:"c",ch:"vin",ic:"quiz",t:I3("Recipienti, rovere e lavorazione delle uve","Contenants, chêne et préparation du raisin","Vessels, oak and grape processing"),s:[
 {h:I3("Il rovere","Le chêne","Oak"),
  c:I3("Quasi tutti i recipienti in legno sono di rovere. Oltre a una leggera ossidazione, il vino estrae dal legno tannini e aromi: i tannini del rovere danno struttura a rossi e bianchi, mentre gli aromi ricordano tostato, vaniglia, fumo e chiodi di garofano. L'igiene è una sfida: è difficile tenere il legno del tutto libero da lieviti, batteri e muffe, e un legno contaminato può rovinare il vino.",
   "Presque tous les contenants en bois sont en chêne. Outre une légère oxydation, le vin extrait du bois des tanins et des arômes : les tanins du chêne structurent rouges et blancs, et les arômes évoquent le toasté, la vanille, la fumée et le clou de girofle. L'hygiène est un défi : il est difficile de garder le bois totalement exempt de levures, bactéries et moisissures, et un bois contaminé peut ruiner le vin.",
   "Almost all wooden winery vessels are oak. Besides gentle oxidation, the wine extracts tannins and flavours from the wood: oak tannins add structure to reds and whites, and the aromas recall toast, vanilla, smoke and cloves. Hygiene is a challenge: it is hard to keep wood completely free of yeasts, bacteria and moulds, and tainted wood can ruin a wine."),
  v:()=>fSvg(fBarrel(110,110,2)+[[w3("tostato","toasté","toast"),240,40],[w3("vaniglia","vanille","vanilla"),260,80],[w3("fumo","fumée","smoke"),240,120],[w3("chiodi di garofano","clou de girofle","cloves"),250,160]].map(([l,x,y],i)=>fD(.4+i*.5,fChip(x,y,l,"#8a5a33"))).join(""))},
 {h:I3("Specie e origine del rovere","Espèce et origine du chêne","Oak species and origin"),
  c:I3("Specie diverse di rovere hanno caratteristiche diverse, e anche la stessa specie cambia secondo dove cresce. La maggior parte dei recipienti è di rovere europeo o americano. Il rovere europeo ha caratteri simili che venga dalla Francia, dall'Ungheria o dalla Russia, ma alcune foreste, soprattutto francesi, sono considerate le migliori.",
   "Différentes espèces de chêne ont des caractéristiques différentes, et une même espèce varie selon l'endroit où elle pousse. La plupart des contenants sont en chêne européen ou américain. Le chêne européen a des caractères proches qu'il vienne de France, de Hongrie ou de Russie, mais certaines forêts, surtout françaises, sont considérées comme les meilleures.",
   "Different oak species have different characteristics, and the same species can vary with where it grows. Most winery vessels are made from European or American oak. European oak is broadly similar whether from France, Hungary or Russia, but some forests, especially in France, are considered the finest."),
  v:()=>fSvg([60,160,260].map((x,i)=>`<g transform="translate(${x} 150)"><path d="M0 0V-40" stroke="#6b4426" stroke-width="8"/><circle cy="-60" r="30" fill="${["#4f7a28","#5e8c31","#3f6a20"][i]}"/></g>`).join("")+fChip(60,180,w3("Francia","France","France"))+fChip(160,180,w3("Ungheria · Russia","Hongrie · Russie","Hungary · Russia"))+fChip(260,180,w3("America","Amérique","America")),"spring")},
 {h:I3("Le dimensioni","La taille","Size"),
  c:I3("I recipienti piccoli, come la barrique bordolese da 225 litri e la pièce borgognona da 228, influiscono molto più di quelli grandi, che possono superare i 2000 litri: in un recipiente piccolo una parte maggiore del vino è a contatto con il legno.",
   "Les petits contenants, comme la barrique bordelaise de 225 litres et la pièce bourguignonne de 228, ont bien plus d'effet que les grands, qui peuvent dépasser 2 000 litres : dans un petit contenant, une plus grande part du vin est au contact du bois.",
   "Small vessels such as the 225-litre barrique and the 228-litre pièce have much more effect than large vessels, which can exceed 2,000 litres: in a small vessel more of the wine is in contact with the wood."),
  v:()=>fSvg(fBarrel(60,120,.9)+fT(60,160,"barrique 225 l",9)+fBarrel(130,120,.92)+fT(130,160,"pièce 228 l",9)+`<ellipse cx="240" cy="104" rx="66" ry="58" fill="url(#fwood)" stroke="#4e321c"/><path d="M178 80H302M178 128H302" stroke="#3a3a3a" stroke-width="3"/>`+fT(240,180,"> 2000 l",10))},
 {h:I3("La tostatura","La chauffe","Toasting"),
  c:I3("Per costruire la botte le doghe vengono scaldate sul fuoco, così si possono piegare. Il calore trasforma anche i tannini e gli aromi del legno, che acquista note di spezie dolci e di tostato. Temperatura e durata del riscaldamento, cioè il grado di tostatura, decidono quali aromi la botte darà al vino.",
   "Pour fabriquer le fût, les douelles sont chauffées au feu afin de pouvoir être cintrées. La chaleur transforme aussi les tanins et les arômes du bois, qui prend des notes d'épices douces et de toasté. La température et la durée de la chauffe, c'est-à-dire le degré de chauffe, décident des arômes que le fût apportera au vin.",
   "To build a barrel the staves are heated over a fire so they can be bent into shape. The heat also transforms the wood's tannins and flavour compounds, giving notes of sweet spice and toast. The temperature and length of heating, the level of toast, decide which flavours the barrel will give the wine."),
  v:()=>fSvg(`<g transform="translate(160 120)">${Array.from({length:12},(_,i)=>`<path d="M${-46+i*8.4} -60Q${-46+i*8.4+(i<6?-6:6)} 0 ${-40+i*7.2} 40" stroke="#8a5a33" stroke-width="7"/>`).join("")}<path d="M-50 -46H50M-46 28H46" stroke="#3a3a3a" stroke-width="3"/></g>`+fFire(160,190)+fD(1.5,fChip(200,40,w3("tostatura leggera · media · forte","chauffe légère · moyenne · forte","light · medium · heavy toast"),"#d9774b")))},
 {h:I3("L'età della botte","L'âge du fût","Barrel age"),
  c:I3("L'effetto della tostatura diminuisce a ogni utilizzo: una botte già usata una volta dà meno aromi di una nuova e, al quarto passaggio, ne cede pochissimi, come pochi tannini. Gli aromi del legno nuovo non vanno bene per tutti i vini, e alcuni produttori evitano le botti nuove per un rovere più discreto.",
   "L'effet de la chauffe diminue à chaque utilisation : un fût déjà utilisé une fois donne moins d'arômes qu'un neuf et, à la quatrième utilisation, il en cède très peu, comme peu de tanins. Les arômes du bois neuf ne conviennent pas à tous les vins, et certains producteurs évitent les fûts neufs pour un boisé plus discret.",
   "The effect of toasting diminishes with each use: a once-used barrel gives less flavour than a new one and, by its fourth use, it imparts little flavour or tannin. New-oak flavours do not suit every wine, and some producers avoid new barrels for subtler oak."),
  v:()=>fSvg([1,2,3,4].map((n,i)=>fD(i*.3,fBarrel(50+i*74,110,.9)+`<rect x="${30+i*74}" y="150" width="40" height="${30-i*7}" fill="#d9774b"/>`+fT(50+i*74,96,`${n}°`,12))).join("")+fT(160,30,w3("aromi ceduti dal legno","arômes cédés par le bois","flavour given by the wood"),10))},
 {h:I3("Le alternative alla botte","Les alternatives au fût","Oak alternatives"),
  c:I3("Gli aromi e i tannini del rovere si possono ottenere anche senza botti: si immergono nel vino, in un recipiente inerte, doghe o trucioli di rovere, durante la fermentazione o l'affinamento, a un costo molto più basso. L'effetto ossidativo della botte si può imitare aggiungendo ossigeno in piccole dosi controllate. Sono tecniche ancora molto studiate e di solito non si usano per i vini di alta gamma.",
   "Les arômes et tanins du chêne peuvent s'obtenir sans fût : on plonge dans le vin, en cuve inerte, des douelles ou des copeaux de chêne, pendant la fermentation ou l'élevage, pour un coût bien plus bas. L'effet oxydatif du fût peut être imité en ajoutant de l'oxygène en petites doses contrôlées. Ces techniques sont encore très étudiées et ne s'emploient généralement pas pour les vins haut de gamme.",
   "Oak flavours and tannins can be obtained without barrels: oak staves or chips are put into the wine in an inert vessel, during fermentation or maturation, at a far lower cost. The oxidative effect of barrel ageing can be mimicked by adding small, controlled doses of oxygen. These techniques are still widely researched and are not normally used for premium wines."),
  v:()=>fSvg(STEEL(100,40,120,130,{col:WHITE,lv:.75})+`<g>${Array.from({length:12},(_,i)=>`<rect x="${120+(i*13)%84}" y="70" width="6" height="3" fill="#8a5a33"><animate attributeName="y" from="40" to="${100+(i%5)*12}" dur="1.6s" begin="${i*.1}s" fill="freeze"/></rect>`).join("")}</g>`+fD(1.8,`<path d="M240 160H270V60" stroke="#9fd3f0" stroke-width="2" fill="none"/>${[0,1,2].map(i=>`<circle cx="210" cy="160" r="2" fill="#9fd3f0"><animate attributeName="cy" from="160" to="${110-i*12}" dur="1.6s" begin="${i*.5}s" repeatCount="indefinite"/></circle>`).join("")}`+fChip(270,46,"micro-O₂"))+fChip(60,60,w3("trucioli · doghe","copeaux · douelles","chips · staves"),"#8a5a33"))},
 {h:I3("Recipienti inerti: acciaio e cemento","Contenants inertes : inox et béton","Inert vessels: steel and concrete"),
  c:I3("I recipienti inerti non danno aromi e non lasciano entrare ossigeno. La maggior parte è di acciaio inox: facile da pulire, di ogni forma e misura, con sistemi di controllo della temperatura, camicie esterne o serpentine interne dove circola liquido freddo o caldo. Il cemento, rivestito di resina epossidica, era comune prima dell'acciaio: è meno facile da pulire, ma le pareti spesse regolano la temperatura senza impianti costosi. Di recente vanno di moda le vasche a uovo, che favorirebbero il movimento naturale del vino. Anche la bottiglia di vetro è un recipiente inerte.",
   "Les contenants inertes n'apportent pas d'arômes et ne laissent pas entrer l'oxygène. La plupart sont en inox : faciles à nettoyer, de toutes formes et tailles, avec des systèmes de régulation thermique, chemises extérieures ou serpentins intérieurs où circule un liquide froid ou chaud. Le béton, revêtu de résine époxy, était courant avant l'inox : moins facile à nettoyer, ses parois épaisses régulent la température sans équipement coûteux. Les cuves en forme d'œuf sont à la mode et favoriseraient le mouvement naturel du vin. La bouteille en verre est aussi un contenant inerte.",
   "Inert vessels add no flavour and let in no oxygen. Most are stainless steel: easy to clean, any shape or size, with temperature control built in, external jackets or internal coils carrying cold or hot liquid. Epoxy-lined concrete was common before stainless steel: it is harder to clean, but its thick walls regulate temperature without costly equipment. Egg-shaped concrete vats have become fashionable and are thought to aid the wine's natural flow. Glass bottles are inert vessels too."),
  v:()=>fSvg(STEEL(30,40,90,130,{col:WHITE,lv:.7,cold:1,lab:w3("acciaio","inox","steel")})+`<rect x="140" y="60" width="80" height="110" rx="6" fill="#b8b1a6" stroke="#8e877c"/>`+fT(180,186,w3("cemento","béton","concrete"),9)+fEgg(275,170)+fT(275,190,w3("uovo","œuf","egg"),9))},
 {h:I3("Ricevimento e cernita","Réception et tri","Grape reception and sorting"),
  c:I3("Di solito l'uva riceve la prima dose di anidride solforosa appena arriva in cantina. Per i vini di alta gamma passa su un tavolo di cernita, dove si scartano a mano gli acini acerbi o marci. Una selezione così accurata è raramente possibile nelle grandi produzioni.",
   "En général le raisin reçoit sa première dose de dioxyde de soufre dès son arrivée au chai. Pour les vins haut de gamme, il passe sur une table de tri où l'on écarte à la main les baies pas mûres ou pourries. Une sélection aussi soignée est rarement possible dans les grandes productions.",
   "Grapes usually get their first dose of sulfur dioxide as they arrive at the winery. For premium wines they pass over a sorting table where unripe or rotten berries are removed by hand. Such careful selection is rarely possible in high-volume production."),
  v:()=>fSvg(fConveyor(30,140,260)+fMan(110,136,.9,"#8c1d40")+fMan(200,136,.9,"#1f6f6b")+fChip(80,40,"SO₂")+fD(1.4,fChip(230,40,w3("scarti: acerbi, marci","écarts : verts, pourris","rejects: unripe, rotten"),"#b5334a")))},
 {h:I3("Diraspatura e pigiatura","Éraflage et foulage","Destemming and crushing"),
  c:I3("Sono due operazioni facoltative. L'uva vendemmiata a macchina arriva già senza raspi, e anche con quella raccolta a mano la maggior parte dei produttori li toglie, con una macchina che poi può anche pigiare. La pigiatura rompe le bucce e libera parte del succo, il mosto fiore, ma non deve rompere i semi: rilascerebbero oli amari e tannini, rendendo il vino amaro e astringente.",
   "Ce sont deux opérations facultatives. Le raisin vendangé à la machine arrive déjà sans rafles, et même avec la vendange manuelle la plupart des producteurs les retirent, avec une machine qui peut ensuite fouler. Le foulage rompt les peaux et libère une partie du jus, le jus de goutte, mais ne doit pas écraser les pépins : ils libéreraient huiles amères et tanins, rendant le vin amer et astringent.",
   "Both are optional. Machine-harvested grapes arrive without stems, and even with hand-picked fruit most winemakers remove them, in a machine that can then crush the berries. Crushing breaks the skins and releases some juice, the free-run juice, but must not damage the seeds: they would release bitter oils and tannin, making the wine bitter and astringent."),
  v:()=>fSvg(fDestemmer(150,110)+`<rect x="110" y="140" width="80" height="34" rx="4" fill="#4a3832" stroke="#6b5148"/>`+fT(150,190,w3("mosto fiore","jus de goutte","free-run juice"),9)+fT(250,140,w3("raspi","rafles","stems"),9,"#c7d6a5")+fD(1.6,fChip(60,40,w3("semi intatti!","pépins intacts !","seeds intact!"),"#b5334a")))},
 {h:I3("La pressatura","Le pressurage","Pressing"),
  c:I3("La pressatura separa la parte liquida da quella solida. Per i bianchi avviene prima della fermentazione, per i rossi di solito dopo; anche qui i semi non vanno rotti, e le tecniche moderne premono dolcemente. Le presse verticali tradizionali, o a cesto, schiacciano dall'alto con un piatto, e si usano ancora, per esempio in Champagne. Le presse pneumatiche hanno una membrana di gomma che si gonfia dentro un cilindro orizzontale forato, e alcune lavorano chiuse, senza ossigeno. Il succo di inizio e di fine pressatura è diverso: il produttore può separarne le frazioni e assemblarle a piacere.",
   "Le pressurage sépare la partie liquide de la partie solide. Pour les blancs il a lieu avant la fermentation, pour les rouges en général après ; là encore les pépins ne doivent pas être écrasés, et les techniques modernes pressent en douceur. Les pressoirs verticaux traditionnels, ou à corbeille, pressent par le haut avec un plateau et sont toujours utilisés, par exemple en Champagne. Les pressoirs pneumatiques ont une membrane en caoutchouc qui gonfle dans un cylindre horizontal perforé, et certains fonctionnent fermés, sans oxygène. Le jus de début et de fin de pressurage diffère : le vinificateur peut séparer les fractions et les assembler à son gré.",
   "Pressing separates the liquid from the solids. For whites it happens before fermentation, for reds usually after; again the seeds must not be crushed, and modern techniques press gently. Traditional vertical basket presses squeeze from above with a plate and are still widely used, for instance in Champagne. Pneumatic presses have an inflatable rubber bladder inside a perforated horizontal cylinder, and some work enclosed, without oxygen. Juice from the start and end of pressing differs: winemakers can separate the press fractions and blend them as they wish."),
  v:()=>fSvg(fBasketPress(70,150)+fPress(170,70,WHITE,"#a9b94a")+fT(70,190,w3("a cesto","à corbeille","basket"),9)+fT(225,190,w3("pneumatica","pneumatique","pneumatic"),9)+fD(2,fChip(225,40,w3("frazioni di pressatura","fractions de presse","press fractions"))))},
 {h:I3("Arricchimento e concentrazione","Enrichissement et concentration","Enrichment and concentration"),
  c:I3("Nei climi freschi l'uva può avere troppo poco zucchero per un grado alcolico soddisfacente. Il mosto si può allora arricchire con mosto concentrato rettificato, un liquido sciropposo incolore e inodore, prima o durante la fermentazione: più zucchero significa più alcol. È vietato in molte zone e altrove molto regolato; usato male dà vini duri e magri. Se lo zucchero viene da altre fonti, come la barbabietola, si parla di zuccheraggio, o chaptalisation. In alternativa si può togliere acqua dal mosto, ma si concentrano anche tannini, acidi e difetti e si riduce il volume. Lo zucchero è difficile da togliere, mentre l'alcol si può ridurre dopo la fermentazione.",
   "En climat frais le raisin peut manquer de sucre pour un degré satisfaisant. On peut alors enrichir le moût avec du moût concentré rectifié, un liquide sirupeux incolore et inodore, avant ou pendant la fermentation : plus de sucre donne plus d'alcool. C'est interdit dans beaucoup de régions et strictement encadré ailleurs ; mal utilisé il donne des vins durs et maigres. Si le sucre vient d'autres sources, comme la betterave, on parle de chaptalisation. On peut aussi retirer de l'eau du moût, mais on concentre tanins, acides et défauts et on réduit le volume. Le sucre est difficile à retirer, tandis que l'alcool peut être réduit après la fermentation.",
   "In cool climates grapes may have too little sugar for a satisfactory alcohol level. The juice, or must, can then be enriched with rectified concentrated grape must (RCGM), a colourless, odourless syrup, before or during fermentation: more sugar means more alcohol. It is banned in many places and tightly controlled elsewhere; if abused it gives hard, thin wines. When the sugar comes from other sources, such as sugar beet, it is called chaptalisation. Alternatively water can be removed from the juice, but this also concentrates tannins, acids and faults and reduces volume. Sugar is hard to remove, but alcohol can be reduced after fermentation."),
  v:()=>fSvg(STEEL(120,40,90,124,{col:"#d6cc86",lv:.6})+`<g><animateTransform attributeName="transform" type="rotate" values="0 70 50;40 70 50;40 70 50;0 70 50" dur="3s" repeatCount="indefinite"/><path d="M50 30h40v40h-40z" fill="#fbf3e2"/>${fT(70,56,"MCR",9,"#8c1d40")}</g>`+fDrops(110,70,100,"#fbf3e2",3)+fD(1.4,fChip(260,60,"chaptalisation","#8c1d40"))+fD(2.2,fChip(260,120,w3("concentrazione: tutto aumenta","concentration : tout augmente","concentration: everything rises"))))},
 {h:I3("Correggere l'acidità","Corriger l'acidité","Adjusting acidity"),
  c:I3("Se durante la maturazione l'acidità è scesa troppo, la si alza aggiungendo acido tartarico in polvere: nell'UE è permesso solo nelle regioni calde, ed è comune in molte zone calde del mondo. La disacidificazione, cioè ridurre l'acidità, è più frequente nei climi freschi, quando l'acidità non è calata abbastanza: l'eccesso si neutralizza con una sostanza alcalina.",
   "Si l'acidité a trop baissé pendant la maturation, on l'augmente en ajoutant de l'acide tartrique en poudre : dans l'UE c'est permis seulement dans les régions chaudes, et c'est courant dans de nombreuses régions chaudes du monde. La désacidification, c'est-à-dire réduire l'acidité, est plus fréquente en climat frais, quand l'acidité n'a pas assez baissé : l'excès est neutralisé par une substance alcaline.",
   "If acidity has fallen too far during ripening it can be raised by adding tartaric acid powder: in the EU this is allowed only in warmer regions, and it is common in many warm and hot regions worldwide. Deacidification, reducing acidity, is more common in cooler climates when grape acid has not fallen enough: the excess is neutralised with an alkali."),
  v:()=>fSvg(`<rect width="160" height="200" fill="rgba(181,51,74,.2)"/><rect x="160" width="160" height="200" fill="rgba(79,168,162,.2)"/>`+fSun(80,40,14)+fCloud(240,40,1.2,"#b3bac2")+fBox(10,66,140,44,w3("clima caldo: + acido tartarico","climat chaud : + acide tartrique","warm: + tartaric acid"),{fill:"rgba(181,51,74,.75)"})+fBox(170,66,140,44,w3("clima fresco: − acidità (alcali)","climat frais : − acidité (alcalin)","cool: − acid (alkali)"),{fill:"rgba(43,122,117,.75)"})+fGlass(80,160,WHITE,1)+fGlass(240,160,WHITE,1))}
]},
{id:"wm3",sec:"c",ch:"vin",ic:"quiz",t:I3("Fermentazioni, affinamento e imbottigliamento","Fermentations, élevage et mise en bouteille","Fermentations, maturation and bottling"),s:[
 {h:I3("La fermentazione alcolica","La fermentation alcoolique","Alcoholic fermentation"),
  c:I3("È la trasformazione dello zucchero in alcol e anidride carbonica da parte dei lieviti; si producono anche calore e composti aromatici. Il lievito principale è Saccharomyces cerevisiae, perché tollera livelli alti di alcol e di anidride solforosa. La fermentazione non parte sotto i 5 °C e di solito prosegue finché tutto lo zucchero è consumato.",
   "C'est la transformation du sucre en alcool et en gaz carbonique par les levures ; elle produit aussi de la chaleur et des composés aromatiques. La levure principale est Saccharomyces cerevisiae, car elle tolère des teneurs élevées en alcool et en dioxyde de soufre. La fermentation ne démarre pas en dessous de 5 °C et se poursuit en général jusqu'à ce que tout le sucre soit consommé.",
   "It is the conversion of sugar into alcohol and carbon dioxide by yeast; heat and flavour compounds are also produced. The main yeast is Saccharomyces cerevisiae, because it tolerates high levels of alcohol and sulfur dioxide. Fermentation will not start below 5 °C and normally continues until all the sugar has been consumed."),
  v:()=>fSvg(STEEL(40,40,100,130,{col:WHITE,lv:.75,bub:14})+`<g transform="translate(160 40)">${fT(70,0,w3("zucchero","sucre","sugar"),11)}${fYeast(70,34)}${fArrow("M70 50V70")}${fT(10,92,w3("alcol","alcool","alcohol"),10,"#f3cd8a")}${fT(56,92,"CO₂",10,"#bfe3f5")}${fT(96,92,w3("calore","chaleur","heat"),10,"#f6a43a")}${fT(140,92,w3("aromi","arômes","aromas"),10,"#e8a0c0")}</g>`+fChip(230,170,"S. cerevisiae · > 5 °C"))},
 {h:I3("Quando la fermentazione si ferma","Quand la fermentation s'arrête","When fermentation stops"),
  c:I3("La fermentazione può fermarsi prima della fine: se i lieviti esauriscono i nutrienti, se la temperatura supera i 35 °C, o se lo zucchero è così alto che, insieme all'alcol, blocca i lieviti; nei casi estremi non riescono nemmeno a partire. A volte è il produttore a volerla fermare per lasciare zucchero: uccide i lieviti con anidride solforosa o con acquavite, oppure li toglie con la filtrazione, di solito dopo averla bloccata raffreddando il vino sotto i 5 °C.",
   "La fermentation peut s'arrêter avant la fin : si les levures manquent de nutriments, si la température dépasse 35 °C, ou si le sucre est si élevé qu'avec l'alcool il bloque les levures ; dans les cas extrêmes elles ne parviennent même pas à démarrer. Parfois c'est le vinificateur qui veut l'arrêter pour garder du sucre : il tue les levures au dioxyde de soufre ou à l'eau-de-vie, ou les retire par filtration, en général après l'avoir bloquée en refroidissant le vin sous 5 °C.",
   "Fermentation can stop early: if the yeast run out of nutrients, if the temperature goes above 35 °C, or if sugar is so high that, together with the alcohol, it stops the yeast; in extreme cases they struggle even to start. Sometimes the winemaker wants to stop it to leave sugar: the yeast are killed with sulfur dioxide or grape spirit, or removed by filtration, usually after the ferment has been halted by chilling below 5 °C."),
  v:()=>fSvg(fBox(16,24,90,40,w3("niente nutrienti","plus de nutriments","no nutrients"))+fBox(116,24,90,40,"> 35 °C")+fBox(216,24,90,40,w3("troppo zucchero","trop de sucre","too much sugar"))+fD(1.6,fT(160,96,w3("oppure il produttore la ferma:","ou le vinificateur l'arrête :","or the winemaker stops it:"),10,"#f3cd8a")+fBox(16,110,90,40,"SO₂",{fill:"rgba(181,51,74,.5)"})+fBox(116,110,90,40,w3("acquavite","eau-de-vie","grape spirit"),{fill:"rgba(181,51,74,.5)"})+fBox(216,110,90,40,w3("freddo < 5 °C + filtro","froid < 5 °C + filtre","chill < 5 °C + filter"),{fill:"rgba(79,168,162,.5)"})))},
 {h:I3("Lieviti indigeni o selezionati","Levures indigènes ou sélectionnées","Ambient or cultured yeast"),
  c:I3("Il produttore può affidarsi ai lieviti indigeni presenti sulla pruina e in cantina, oppure aggiungere un ceppo selezionato. I lieviti indigeni possono dare aromi più complessi, ma non si controlla quali lieviti agiscano e i risultati cambiano da una partita all'altra, poco adatto ai grandi volumi. I lieviti selezionati sono ceppi di S. cerevisiae scelti perché affidabili e capaci di dare aromi gradevoli; alcuni sostengono però che limitino la complessità.",
   "Le vinificateur peut compter sur les levures indigènes présentes sur la pruine et au chai, ou ajouter une souche sélectionnée. Les levures indigènes peuvent donner des arômes plus complexes, mais on ne contrôle pas lesquelles agissent et les résultats varient d'un lot à l'autre, peu adapté aux gros volumes. Les levures sélectionnées sont des souches de S. cerevisiae choisies pour leur fiabilité et leurs arômes agréables ; certains estiment toutefois qu'elles limitent la complexité.",
   "Winemakers can rely on ambient yeasts found on the grape bloom and in the winery, or add a cultured strain. Ambient yeasts can give more complex flavours, but nobody controls exactly which yeasts are at work and batches vary, which suits high-volume production poorly. Cultured yeasts are selected strains of S. cerevisiae chosen for reliable performance and attractive flavours; some argue, though, that they limit complexity."),
  v:()=>fSvg(`<circle cx="80" cy="100" r="50" fill="#4e1b44"/>`+[[60,80],[96,90],[74,120],[100,116],[64,104]].map(([x,y],i)=>fYeast(x,y)).join("")+fT(80,170,w3("indigeni: complessità","indigènes : complexité","ambient: complexity"),9)+`<g transform="translate(240 100)"><rect x="-26" y="-40" width="52" height="70" rx="6" fill="#fbf3e2"/>${fT(0,-14,"S. c.",11,"#8c1d40")}${fYeast(0,10)}</g>`+fT(240,170,w3("selezionati: affidabili","sélectionnées : fiables","cultured: reliable"),9))},
 {h:I3("La temperatura di fermentazione","La température de fermentation","Fermentation temperature"),
  c:I3("Se il mosto in fermentazione si scalda troppo, i lieviti muoiono. Controllando la temperatura si influisce anche sugli aromi: a bassa temperatura non si perdono gli aromi più volatili, spesso floreali, e nei bianchi si favoriscono note fruttate; temperature più alte servono per estrarre colore e tannini dalle bucce nere. Molte vasche hanno un proprio sistema di raffreddamento e riscaldamento, e il calore in eccesso si disperde anche con i rimontaggi. Il controllo preciso della temperatura ha migliorato enormemente qualità e costanza dei vini moderni.",
   "Si le moût en fermentation chauffe trop, les levures meurent. En contrôlant la température on influe aussi sur les arômes : à basse température on ne perd pas les arômes les plus volatils, souvent floraux, et dans les blancs on favorise les notes fruitées ; des températures plus hautes servent à extraire couleur et tanins des peaux noires. Beaucoup de cuves ont leur propre système de refroidissement et chauffage, et l'excès de chaleur se dissipe aussi par les remontages. Le contrôle précis de la température a énormément amélioré la qualité et la régularité des vins modernes.",
   "If fermenting wine gets too hot, the yeast die. Controlling temperature also shapes flavour: cool temperatures avoid losing the most volatile aromas, often floral, and encourage fruity notes in whites; higher temperatures are needed to extract colour and tannin from black grape skins. Many vats have their own heating and cooling systems, and excess heat can also be released by pumping over. Precise temperature control has made a huge contribution to the quality and consistency of modern wine."),
  v:()=>fSvg(STEEL(40,40,90,124,{col:WHITE,lv:.75,bub:8,cold:1})+STEEL(190,40,90,124,{col:RED,lv:.75,bub:10,cap:1})+fThermo(140,60,"12–22",.3,"#4fa8a2")+fThermo(290,60,"20–32",.7)+fChip(85,190,w3("fresco: aromi","frais : arômes","cool: aromas"))+fChip(235,190,w3("caldo: colore, tannini","chaud : couleur, tanins","warm: colour, tannin")))},
 {h:I3("La fermentazione malolattica","La fermentation malolactique","Malolactic conversion"),
  c:I3("Di solito avviene dopo la fermentazione alcolica, ad opera dei batteri lattici: trasformano l'acido malico, aspro, lo stesso delle mele, in acido lattico, più morbido, lo stesso del latte. L'acidità si riduce e si ammorbidisce, si formano aromi burrosi e un po' di anidride carbonica. La si favorisce scaldando il vino e non aggiungendo solforosa dopo la fermentazione; la si evita tenendo il vino fresco, con la solforosa o filtrando i batteri.",
   "Elle a lieu en général après la fermentation alcoolique, grâce aux bactéries lactiques : elles transforment l'acide malique, vif, celui des pommes, en acide lactique, plus doux, celui du lait. L'acidité baisse et s'assouplit, des arômes beurrés et un peu de gaz carbonique se forment. On la favorise en réchauffant le vin et en n'ajoutant pas de soufre après la fermentation ; on l'évite en gardant le vin au frais, avec du soufre ou en filtrant les bactéries.",
   "It usually follows alcoholic fermentation and is carried out by lactic acid bacteria: they turn tart malic acid, also found in apples, into softer lactic acid, also found in milk. Acidity falls and softens, and buttery flavours and some carbon dioxide are produced. It is encouraged by warming the wine and not adding sulfur dioxide after fermentation; it is avoided by cool storage, SO₂ or filtering out the bacteria."),
  v:()=>fSvg(`<g transform="translate(70 90)"><circle r="26" fill="#9cc65a"/><path d="M0 -26q4-10 12-12" stroke="#5e4126" stroke-width="3" fill="none"/>${fT(0,48,w3("malico","malique","malic"),10,"#c7e09a")}</g>`+fArrow("M112 90H198",null,1)+[0,1,2].map(i=>`<rect x="${140+i*12}" y="${70+i*6}" width="10" height="4" rx="2" fill="#f3cd8a"><animateTransform attributeName="transform" type="translate" values="0 0;4 -3;0 0" dur="${1+i*.2}s" repeatCount="indefinite"/></rect>`).join("")+`<g transform="translate(250 90)"><path d="M-16 -26h32l-4 10v34q0 8-8 8h-8q-8 0-8-8v-34z" fill="#fbf7ec" stroke="#d8c6b6" stroke-width="2"/>${fT(0,48,w3("lattico","lactique","lactic"),10)}</g>`+fD(1.6,fChip(160,160,w3("+ burroso, − acidità","+ beurré, − acidité","+ buttery, − acidity"),"#d4a23a","#2a1b20")))},
 {h:I3("Le fecce","Les lies","Lees"),
  c:I3("Subito dopo la fermentazione il vino è torbido per i lieviti morti e i frammenti d'uva. Le particelle più pesanti cadono sul fondo in poche ore: sono le fecce grossolane, che se non tolte possono dare odori sgradevoli. Le particelle più piccole si depositano lentamente: sono le fecce fini, che di solito si eliminano poco a poco durante l'affinamento. Per alcuni bianchi però si lasciano a contatto con il vino, per dare aromi e una consistenza più ricca.",
   "Juste après la fermentation, le vin est trouble à cause des levures mortes et des fragments de raisin. Les particules les plus lourdes tombent au fond en quelques heures : ce sont les lies grossières, qui, si on ne les retire pas, peuvent donner des odeurs désagréables. Les plus petites se déposent lentement : ce sont les lies fines, qu'on élimine en général peu à peu pendant l'élevage. Pour certains blancs on les laisse au contact du vin, pour apporter arômes et texture plus riche.",
   "Straight after fermentation the wine is cloudy with dead yeast cells and grape fragments. The heaviest particles fall to the bottom within hours: these are the gross lees, which can cause unpleasant aromas if not removed. Smaller particles settle slowly: these are the fine lees, usually removed gradually during maturation. For some white wines, though, they are kept in contact with the wine to add flavour and a richer texture."),
  v:()=>fSvg(STEEL(50,40,100,130,{col:"#d6cc86",colTo:WHITE,cd:3,lv:.8,sed:1})+fCall(100,164,200,150,w3("fecce grossolane: ore","lies grossières : heures","gross lees: hours"),1.5)+fD(2.4,fBarrel(250,80,1.2,{cut:1,col:WHITE}))+fChip(250,40,w3("fecce fini: contatto voluto","lies fines : contact voulu","fine lees: kept on purpose")))},
 {h:I3("Affinamento prima dell'imbottigliamento","Élevage avant la mise en bouteille","Pre-bottling maturation"),
  c:I3("Non tutti i vini migliorano con un lungo affinamento. Se si vogliono conservare gli aromi primari, il vino si imbottiglia dopo pochi mesi in un recipiente inerte: vale per molti vini economici e anche per alcuni di alta gamma, come un grande Riesling australiano, conservato come un semplice White Zinfandel californiano. Per invecchiare, un vino ha bisogno di tannino, acidità e alcol sufficienti e di aromi capaci di evolvere in modo interessante. Durante l'affinamento il recipiente può dare aromi di legno o ossigeno, i componenti reagiscono tra loro e possono formare sedimenti che si tolgono periodicamente.",
   "Tous les vins ne gagnent pas à un long élevage. Si l'on veut garder les arômes primaires, le vin est mis en bouteille après quelques mois en contenant inerte : c'est le cas de nombreux vins bon marché et aussi de certains haut de gamme, comme un grand Riesling australien, conservé comme un simple White Zinfandel californien. Pour vieillir, un vin a besoin d'assez de tanins, d'acidité et d'alcool, et d'arômes capables d'évoluer de façon intéressante. Pendant l'élevage, le contenant peut apporter des arômes boisés ou de l'oxygène, les composants réagissent entre eux et peuvent former des dépôts qu'on retire régulièrement.",
   "Not every wine benefits from long maturation before bottling. To retain primary fruit, the wine is bottled after a few months in an inert vessel: true of many inexpensive wines and some premium ones too, such as a fine Australian Riesling, stored much like an inexpensive Californian White Zinfandel. To age, a wine needs enough tannin, acidity and/or alcohol, plus flavours that will develop interestingly. During maturation the vessel may add oak flavour or oxygen, components react with each other, and sediment can form and is periodically removed."),
  v:()=>fSvg(STEEL(30,50,80,110,{col:WHITE,lv:.8,lab:w3("pochi mesi","quelques mois","a few months")})+fArrow("M116 110H150")+fBottle(170,124,{col:WHITE,cork:1,label:1})+fD(1.2,fBox(200,30,110,60,w3("per invecchiare: tannino, acidità, alcol + aromi","pour vieillir : tanins, acidité, alcool + arômes","to age: tannin, acid, alcohol + flavour"))))},
 {h:I3("L'assemblaggio","L'assemblage","Blending"),
  c:I3("Quasi tutti i vini sono assemblaggi, anche quelli di una sola varietà. Si può assemblare in ogni momento, ma soprattutto dopo la fermentazione o durante l'affinamento, per tre scopi. Equilibrio: per esempio il vino fiore con un po' di vino di pressa per aumentare i tannini. Costanza: le barrique evolvono in modo un po' diverso e vanno riunite, come vasche di vigneti o vendemmie diverse. Stile: molte case mantengono uno stile riconoscibile nonostante le annate, e moltiplicano le opzioni separando frazioni, recipienti, malolattica, varietà, parcelle e annate, nei limiti delle leggi locali.",
   "Presque tous les vins sont des assemblages, même ceux d'un seul cépage. On peut assembler à tout moment, mais surtout après la fermentation ou pendant l'élevage, dans trois buts. Équilibre : par exemple le vin de goutte avec un peu de vin de presse pour augmenter les tanins. Régularité : les barriques évoluent un peu différemment et doivent être réunies, comme des cuves de parcelles ou de dates de récolte différentes. Style : beaucoup de maisons gardent un style reconnaissable malgré les millésimes, et multiplient les options en séparant fractions, contenants, malolactique, cépages, parcelles et millésimes, dans les limites de la loi.",
   "Almost every wine is a blend, even single-variety wines. Blending can happen at any stage, but mainly after fermentation or during maturation, for three reasons. Balance: for example free-run wine with some press wine to boost tannin. Consistency: barrels develop slightly differently and must be combined, as must vats from different plots or picking dates. Style: many houses keep a recognisable style despite vintage variation, and create options by separating press fractions, vessels, partial MLF, varieties, plots and vintages, within local regulations."),
  v:()=>fSvg([0,1,2,3].map(i=>`<g transform="translate(${40+i*36} 50)">${fBarrel(0,0,.5,{cut:1,col:["#7a1530","#8c2440","#6b1430","#7f1d35"][i]})}</g>`).join("")+[0,1,2,3].map(i=>fArrow(`M${40+i*36} 70Q${120} 120 200 130`,null,1)).join("")+STEEL(200,70,90,110,{col:RED,lv:.75})+fChip(80,170,w3("equilibrio · costanza · stile","équilibre · régularité · style","balance · consistency · style")))},
 {h:I3("Sedimentazione e travaso","Sédimentation et soutirage","Sedimentation and racking"),
  c:I3("I consumatori si aspettano vini limpidi: le tecniche sono tre, sedimentazione, collaggio e filtrazione, anche se alcuni vini di alta gamma ne saltano qualcuna. Dopo la fermentazione le fecce grossolane si depositano e il vino si pompa piano in un altro recipiente lasciandole indietro: è il travaso. Ripetendolo durante l'affinamento il vino diventa sempre più limpido, e per alcuni grandi vini è l'unica chiarifica. La gravità agisce lentamente; si può accelerare con la centrifuga, che però è molto costosa.",
   "Les consommateurs attendent des vins limpides : les techniques sont trois, sédimentation, collage et filtration, même si certains vins haut de gamme en sautent une partie. Après la fermentation, les lies grossières se déposent et le vin est pompé doucement dans un autre contenant en les laissant derrière : c'est le soutirage. En le répétant pendant l'élevage, le vin devient de plus en plus limpide, et pour certains grands vins c'est la seule clarification. La gravité agit lentement ; on peut accélérer avec une centrifugeuse, très coûteuse.",
   "Consumers expect clear wine: there are three techniques, sedimentation, fining and filtration, though some premium wines skip some of them. After fermentation the gross lees settle and the wine is slowly pumped into another vessel, leaving them behind: this is racking. Repeated rackings during maturation make the wine ever clearer, and for some fine wines this is the only clarification. Gravity acts slowly; a centrifuge speeds things up but is very expensive."),
  v:()=>fSvg(STEEL(30,50,90,120,{col:RED,lv:.75,sed:1})+fD(1.5,`<path d="M110 140H150V120H180" stroke="#d4a23a" stroke-width="3" fill="none" stroke-dasharray="5 4"><animate attributeName="stroke-dashoffset" from="18" to="0" dur=".8s" repeatCount="indefinite"/></path>`+STEEL(180,70,80,100,{col:RED,lv:.3,colTo:RED}))+fCentrifuge(290,170)+fT(290,190,w3("centrifuga","centrifugeuse","centrifuge"),8.5))},
 {h:I3("Il collaggio","Le collage","Fining"),
  c:I3("A volte velature o depositi compaiono solo dopo un po' di tempo in bottiglia, perché alcuni componenti si aggregano lentamente fino a diventare visibili. Il collaggio accelera questo processo: si aggiunge un chiarificante, una sostanza che si lega a certi componenti e forma grumi visibili, poi eliminati con la filtrazione. È molto diffuso per la stabilità, ma alcuni produttori lo evitano perché temono che peggiori aroma e consistenza.",
   "Parfois des troubles ou des dépôts n'apparaissent qu'après un temps en bouteille, car certains composants s'agglomèrent lentement jusqu'à devenir visibles. Le collage accélère ce processus : on ajoute une colle, une substance qui se lie à certains composants et forme des amas visibles, ensuite éliminés par filtration. Il est très répandu pour la stabilité, mais certains producteurs l'évitent car ils craignent qu'il nuise aux arômes et à la texture.",
   "Hazes or deposits sometimes appear only after time in bottle, because some components slowly clump together until visible. Fining speeds this up: a fining agent is added that bonds with certain wine components to form visible clumps, which are then removed by filtering. It is widely practised for stability, but some winemakers avoid it, believing it can harm flavour and texture."),
  v:()=>fSvg(STEEL(110,40,100,130,{col:"#c9be72",colTo:WHITE,cd:4,lv:.8})+Array.from({length:10},(_,i)=>`<circle cx="${125+(i*9)%70}" cy="70" r="1.6" fill="#8a7a55"><animate attributeName="r" from="1.6" to="4" begin="${1+i*.15}s" dur="1s" fill="freeze"/><animate attributeName="cy" from="${70+(i%3)*14}" to="160" begin="${2+i*.15}s" dur="1.6s" fill="freeze"/></circle>`).join("")+`<g><animateTransform attributeName="transform" type="rotate" values="0 70 50;40 70 50;40 70 50;0 70 50" dur="3s" repeatCount="indefinite"/><path d="M50 30h40v40h-40z" fill="#fbf3e2"/></g>`+fChip(70,100,w3("chiarificante","colle","fining agent")))},
 {h:I3("La filtrazione","La filtration","Filtration"),
  c:I3("La filtrazione toglie fisicamente le particelle facendo passare il vino attraverso un filtro, dopo la fermentazione, durante l'affinamento e di solito prima dell'imbottigliamento. I filtri di profondità sono uno strato spesso di materiale che trattiene le particelle al suo interno: reggono vini molto torbidi e servono a togliere le fecce grossolane. I filtri di superficie sono come setacci finissimi che trattengono le particelle in superficie: costosi e facili da intasare, si usano dopo un filtro di profondità. Se i pori fermano anche lieviti e batteri si parla di filtrazione sterile, l'ultimo passaggio prima della bottiglia. Alcuni vini però si imbottigliano non filtrati.",
   "La filtration retire physiquement les particules en faisant passer le vin à travers un filtre, après la fermentation, pendant l'élevage et en général avant la mise en bouteille. Les filtres en profondeur sont une épaisse couche de matériau qui retient les particules à l'intérieur : ils supportent des vins très troubles et servent à retirer les lies grossières. Les filtres de surface sont comme des tamis très fins qui retiennent les particules en surface : chers et vite colmatés, on les utilise après un filtre en profondeur. Si les pores arrêtent aussi levures et bactéries, on parle de filtration stérile, dernière étape avant la bouteille. Certains vins sont toutefois mis en bouteille non filtrés.",
   "Filtration physically removes particles by passing the wine through a filter, after fermentation, during maturation and usually before bottling. Depth filters are a thick layer of material that traps particles inside it: they cope with very cloudy wine and can remove the gross lees. Surface filters are like very fine sieves that trap particles on their surface: expensive and easily clogged, they are used after a depth filter. When the pores are small enough to remove yeast and bacteria, this is sterile filtration, a final step before bottling. Some wines, though, are bottled unfiltered."),
  v:()=>fSvg(fFilterDepth(90,140)+fFilterSurface(230,140)+fT(90,170,w3("di profondità","en profondeur","depth"),9.5)+fT(230,170,w3("di superficie · sterile","de surface · stérile","surface · sterile"),9.5)+fArrow("M136 110H190",null,1))},
 {h:I3("La stabilizzazione tartarica","La stabilisation tartrique","Tartrate stabilisation"),
  c:I3("Un vino è stabile quando, nel tempo previsto, cambia in modo lento e prevedibile: un rosso economico da bere entro un anno non deve fare depositi, mentre un Vintage Port invecchiato decenni ne avrà parecchi. L'acido tartarico è meno solubile nel vino che nel mosto e col tempo forma cristalli: trasparenti nei bianchi, viola nei rossi. Sono innocui e insapori, ma ai consumatori non piacciono. Il freddo li fa formare, quindi un lungo affinamento in cantina fresca ne elimina una parte; altrimenti si raffredda il vino sotto 0 °C per poco tempo e si filtrano i cristalli.",
   "Un vin est stable quand, sur la période prévue, il évolue de façon lente et prévisible : un rouge bon marché à boire dans l'année ne doit pas déposer, alors qu'un Vintage Port vieilli des décennies aura un dépôt épais. L'acide tartrique est moins soluble dans le vin que dans le moût et forme avec le temps des cristaux : transparents dans les blancs, violets dans les rouges. Inoffensifs et sans goût, ils déplaisent aux consommateurs. Le froid les fait apparaître, donc un long élevage en cave fraîche en élimine une partie ; sinon on refroidit le vin sous 0 °C peu de temps et on filtre les cristaux.",
   "A wine is stable if, over its expected life, it changes slowly and predictably: an inexpensive red to drink within a year should not throw a deposit, while a Vintage Port aged for decades will throw a thick one. Tartaric acid is less soluble in wine than in juice and over time forms crystals called tartrates: clear in white wine, purple in red. They are harmless and flavourless but put consumers off. Cold makes them form, so a long maturation in a cool cellar removes some; otherwise the wine is chilled below 0 °C for a short time and the crystals are filtered out."),
  v:()=>fSvg(STEEL(40,40,90,130,{col:WHITE,lv:.75,cold:1,lab:"< 0 °C"})+fCrystals(60,150)+fBottle(200,120,{col:WHITE})+fBottle(260,120,{col:RED})+fD(1,fCrystals(190,148,"#fff")+fCrystals(250,148,"#b07ab0")))},
 {h:I3("Stabilità microbiologica e ossigeno","Stabilité microbiologique et oxygène","Microbiological and oxygen stability"),
  c:I3("Molti lieviti e batteri possono rovinare un vino e prosperano nei residui: le attrezzature vanno tenute pulitissime. Solo i fortificati sono al sicuro, perché il loro alcol è tossico per tutti i microrganismi. Un vino secco, molto acido e che ha fatto la malolattica resiste bene, e alcuni preferiscono non filtrarlo sterile. Sono invece a rischio i vini senza malolattica, con alcol medio-basso, poca acidità e un po' di zucchero: servono solforosa e filtrazione sterile. Contro l'ossigeno si tiene la solforosa al giusto livello e si lavano le bottiglie con anidride carbonica o azoto prima del riempimento.",
   "De nombreuses levures et bactéries peuvent gâter un vin et prospèrent dans les résidus : le matériel doit être impeccablement propre. Seuls les vins mutés sont à l'abri, car leur alcool est toxique pour tous les micro-organismes. Un vin sec, très acide et ayant fait sa malolactique résiste bien, et certains préfèrent ne pas le filtrer stérile. Sont en revanche à risque les vins sans malolactique, à alcool faible ou moyen, peu acides et avec un peu de sucre : il faut du soufre et une filtration stérile. Contre l'oxygène, on garde le soufre au bon niveau et on purge les bouteilles au gaz carbonique ou à l'azote avant le remplissage.",
   "Many yeasts and bacteria can spoil wine and thrive in residues, so equipment must be kept spotless. Only fortified wines are safe, because their alcohol is toxic to all microorganisms. A dry, high-acid wine that has gone through MLF is quite resistant, and some winemakers choose not to sterile filter it. At risk are wines without MLF, with low to medium alcohol, low acidity and some residual sugar: they need SO₂ and sterile filtration. Against oxygen, SO₂ is kept topped up and bottles are flushed with carbon dioxide or nitrogen before filling."),
  v:()=>fSvg(fBox(16,24,140,56,w3("a rischio: niente MLF, poco alcol, poca acidità, zucchero","à risque : sans FML, peu d'alcool, peu d'acidité, sucre","at risk: no MLF, low alcohol, low acid, sugar"),{fill:"rgba(181,51,74,.5)"})+fBox(166,24,140,56,w3("al sicuro: fortificati","à l'abri : vins mutés","safe: fortified wines"),{fill:"rgba(94,140,49,.5)"})+fBottle(120,150,{col:WHITE})+fD(1,`<path d="M120 80V104" stroke="#9fd3f0" stroke-width="3"/>`+fChip(200,110,w3("bottiglia lavata con CO₂/N₂","bouteille purgée CO₂/N₂","bottle flushed with CO₂/N₂"),"#2b7a75")))},
 {h:I3("Il confezionamento","Le conditionnement","Packaging"),
  c:I3("Quasi tutto il vino si vende in bottiglie di vetro: portatili, economiche, robuste, non lasciano entrare aria e non alterano il gusto. Sono però pesanti e rigide: pesano sul trasporto e, una volta aperte, lasciano aria nella bottiglia. Per questo si usa vetro più leggero o si spedisce il vino sfuso per imbottigliarlo vicino al mercato. Le bottiglie di plastica sono più leggere ma lasciano passare un po' d'aria, e il vino perde freschezza in pochi mesi. Il bag-in-box si affloscia mentre si beve, ma un po' d'aria passa dal sacchetto: va consumato entro circa 18 mesi. Per invecchiare, il vetro resta la scelta migliore.",
   "Presque tout le vin se vend en bouteilles de verre : portables, bon marché, solides, elles ne laissent pas entrer l'air et n'altèrent pas le goût. Mais elles sont lourdes et rigides : elles pèsent sur le transport et, une fois ouvertes, laissent de l'air dans la bouteille. D'où le verre allégé ou l'expédition en vrac pour embouteiller près du marché. Les bouteilles en plastique sont plus légères mais laissent passer un peu d'air, et le vin perd sa fraîcheur en quelques mois. Le bag-in-box se rétracte au fur et à mesure, mais un peu d'air traverse la poche : il se consomme dans les 18 mois environ. Pour vieillir, le verre reste le meilleur choix.",
   "Most wine is sold in glass bottles: portable, cheap, strong, airtight and taint-free. But they are heavy and rigid: weight adds transport costs and, once opened, a part-full bottle holds air. Hence lighter glass, or shipping wine in bulk to be bottled nearer the market. Plastic bottles are much lighter but let small amounts of air through, so wine loses freshness within months. Bag-in-box collapses as the wine is drunk, but some air passes through the bag: it should be used within about 18 months. For long ageing, glass remains the best option."),
  v:()=>fSvg(fBottle(60,130,{col:RED,cork:1,label:1})+fPET(140,166,WHITE)+fBIB(230,170)+fT(60,190,w3("vetro","verre","glass"),9)+fT(140,190,w3("plastica: mesi","plastique : mois","plastic: months"),9)+fT(230,190,"bag-in-box ≈ 18",9))},
 {h:I3("I tappi","Les bouchons","Closures"),
  c:I3("Il sughero è la chiusura originaria e ancora la più diffusa; per i vini da invecchiare lascia entrare pochissimo ossigeno, un equilibrio ideale tra aromi primari e terziari per molti produttori. Una piccola percentuale di bottiglie però sa di tappo, per il TCA, che dà odore di muffa e cartone, e altre lasciano entrare troppo ossigeno. I tappi sintetici, di plastica, un tempo solo per vini da bere entro un anno, oggi hanno versioni di qualità per conservazioni più lunghe. Il tappo a vite non altera il vino, chiude ermeticamente e conserva più a lungo il frutto; si discute ancora sull'invecchiamento e alcuni oggi lasciano passare un po' d'ossigeno. Ogni mercato ha le sue preferenze.",
   "Le liège est la fermeture d'origine et reste la plus répandue ; pour les vins de garde il laisse entrer très peu d'oxygène, un équilibre idéal entre arômes primaires et tertiaires pour beaucoup de producteurs. Une petite part des bouteilles est toutefois bouchonnée, à cause du TCA, qui sent le moisi et le carton, et d'autres laissent entrer trop d'oxygène. Les bouchons synthétiques, en plastique, autrefois réservés aux vins à boire dans l'année, existent aujourd'hui en versions de qualité pour une garde plus longue. La capsule à vis n'altère pas le vin, ferme hermétiquement et conserve plus longtemps le fruit ; on débat encore du vieillissement et certaines laissent désormais passer un peu d'oxygène. Chaque marché a ses préférences.",
   "Cork is the original closure and still the most widely used; for wines meant to age it lets in a very small amount of oxygen, an ideal balance of primary and tertiary characters for many winemakers. A small percentage of bottles suffer cork taint from TCA, smelling mouldy and of cardboard, and others let in too much oxygen. Synthetic corks, plastic, once only for wines drunk within a year, now come in premium versions for longer storage. Screw caps do not taint, give an airtight seal and preserve fruit longer; their suitability for long ageing is still debated and some now allow a little oxygen through. Each market has its own preferences."),
  v:()=>fSvg([["cork",50,w3("sughero","liège","cork")],["spark",110,w3("spumante","effervescent","sparkling")],["stopper",170,w3("a fungo","bouchon tête","stopper")],["synth",230,w3("sintetico","synthétique","synthetic")],["screw",290,w3("a vite","à vis","screw cap")]].map(([k,x,l],i)=>fD(i*.25,fClosure(k,x,110)+fT(x,130,l,8.5))).join("")+fD(1.6,fChip(50,160,"TCA","#b5334a")))},
 {h:I3("L'affinamento in bottiglia","Le vieillissement en bouteille","Post-bottling maturation"),
  c:I3("La maggior parte dei vini va bevuta entro un anno dall'imbottigliamento: invecchiando perderebbe il frutto fresco. Alcuni invece migliorano in bottiglia per anni e non danno il meglio subito: per esempio il Vintage Port, i grandi Riesling tedeschi e i crus classés di Bordeaux. La chimica di questo processo è ancora poco conosciuta, ma si sa come conservarli: al buio, al fresco, a temperatura costante, idealmente tra 10 e 15 °C, con umidità costante e, se chiusi con il sughero, coricati, perché il tappo resti umido e sigilli bene.",
   "La plupart des vins se boivent dans l'année qui suit la mise en bouteille : en vieillissant ils perdraient leur fruit frais. Certains en revanche s'améliorent en bouteille pendant des années et ne sont pas à leur meilleur tout de suite : par exemple le Vintage Port, les grands Rieslings allemands et les crus classés de Bordeaux. La chimie de ce processus reste mal connue, mais on sait comment les garder : dans l'obscurité, au frais, à température constante, idéalement entre 10 et 15 °C, avec une humidité constante et, s'ils sont bouchés au liège, couchés, pour que le bouchon reste humide et étanche.",
   "Most wines are best drunk within a year of bottling: ageing would lose their fresh fruit. Some, however, mature in bottle for years and are not at their best at first: for example Vintage Port, the finest German Rieslings and Bordeaux crus classés. The chemistry is still poorly understood, but storage is clear: undisturbed in a cool, dark place at a constant temperature, ideally 10–15 °C, with constant humidity and, if sealed with cork, lying down so the cork stays moist and seals well."),
  v:()=>fSvg([0,1,2].map(r=>[0,1,2,3,4].map(c=>`<g transform="translate(${50+c*50} ${60+r*40}) rotate(90)">${fBottle(0,0,{col:RED,cork:1})}</g>`).join("")).join("")+fThermo(296,40,"10–15 °C",.35,"#4fa8a2"))}
]}
);
